#!/usr/bin/env bun
/**
 * LIMINAL — themes, side by side.
 *
 * The same system at five brand hues. Every value is generated by
 * `createLiminalTheme`, and the numbers under each column are measured from the
 * generated ladder rather than typed.
 *
 * The claim this page has to show: changing the hue does not change how far
 * apart the surfaces look. The step is a perceptual quantum — it does not
 * depend on which colour the ladder is.
 */
import { writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createLiminalTheme } from '../src/engine/liminal-theme';
import { LADDER, LADDER_HUE, PERCEPTUAL_QUANTUM } from '../src/engine/liminal-ladder';
import { hexToRgb, rgbToOklch, contrastRatioHex } from '../src/engine/liminal-color-math';
import { getTextStyle } from '../src/engine/spec-engine';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(__dirname, '../design-lab/themes.html');

const THEMES = [
  { name: 'liminal', hue: LADDER_HUE, label: 'LIMINAL', note: 'هیوی خودِ سیستم — مرجع' },
  { name: 'forest', hue: 145, label: 'Forest', note: 'سبز' },
  { name: 'ember', hue: 35, label: 'Ember', note: 'نارنجی' },
  { name: 'plum', hue: 320, label: 'Plum', note: 'بنفش-سرخ' },
  { name: 'abyss', hue: 215, label: 'Abyss', note: 'آبی سرد' },
];

const TEXT = getTextStyle('primary', 2).color as string;
const DIM = getTextStyle('secondary', 2).color as string;
const FAINT = getTextStyle('tertiary', 2).color as string;

const lum = (hex: string) => rgbToOklch(hexToRgb(hex)).L;

const column = (t: ReturnType<typeof createLiminalTheme>, label: string, note: string) => {
  const steps = t.ladder.slice(1).map((h, i) => (lum(h) - lum(t.ladder[i])) / PERCEPTUAL_QUANTUM);
  const minQ = Math.min(...steps).toFixed(2);
  const maxQ = Math.max(...steps).toFixed(2);
  const contrast = contrastRatioHex(t.ladder[0], t.ladder[8]).toFixed(2);
  return `
  <div class="col">
    <div class="head">
      <b>${label}</b>
      <span class="mono">${t.brandHue}°</span>
      <span class="use">${note}</span>
    </div>
    <div class="stack">
      ${t.ladder.map((hex, i) => `
        <div class="step" style="background:${hex}">
          <span class="mono">S${i}</span>
          <span class="mono dim">${hex}</span>
        </div>`).join('')}
    </div>
    <div class="nums">
      <div><span class="k">گام</span><span class="v mono">${minQ}q – ${maxQ}q</span></div>
      <div><span class="k">کنتراست S0↔S8</span><span class="v mono">${contrast}:1</span></div>
    </div>
    ${t.warnings.length
      ? `<div class="warn">⚠ ${t.warnings.map((w) => `S${w.level} = ${w.q.toFixed(2)}q`).join(' · ')}<br><span class="use">این هیو گامی زیر کوانتوم دارد — دو سطح مجاور از هم قابل‌تشخیص نیستند</span></div>`
      : `<div class="ok">✓ همه‌ی گام‌ها بالای کوانتوم</div>`}
    <div class="demo" style="background:${t.ladder[2]}; border-color:${t.ladder[3]}">
      <div class="card" style="background:${t.ladder[4]}; border-color:${t.ladder[5]}">
        <span style="color:${TEXT}">پنل روی سطح کار</span>
        <span class="use" style="color:${DIM}">متن ثانویه</span>
      </div>
      <button class="btn" style="background:${t.ladder[6]}; border-color:${t.ladder[7]}; color:${TEXT}">دکمه</button>
    </div>
  </div>`;
};

const cols = THEMES.map((th) => column(createLiminalTheme({ brandHue: th.hue, name: th.name }), th.label, th.note)).join('');

const html = `<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>LIMINAL — تم‌ها</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body { margin:0; background:${LADDER[0]}; color:${TEXT};
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; font-size:15px; line-height:1.7; }
  .wrap { max-width:1400px; margin:0 auto; padding:48px 24px 96px; }
  h1 { font-size:30px; margin:0 0 6px; font-weight:700; letter-spacing:-0.02em; }
  .eyebrow { font-family:ui-monospace,monospace; font-size:11px; color:${FAINT}; letter-spacing:.1em; text-transform:uppercase; }
  .lede { color:${DIM}; max-width:80ch; margin:0 0 8px; }
  .claim { border-inline-start:2px solid ${LADDER[3]}; padding-inline-start:14px; margin:18px 0 32px; color:${DIM}; max-width:80ch; }
  .claim b { color:${TEXT}; }
  .grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(240px,1fr)); gap:18px; }
  .col { border:1px solid ${LADDER[3]}; border-radius:14px; padding:16px; background:${LADDER[1]}; }
  .head { display:flex; flex-direction:column; gap:2px; margin-bottom:12px; }
  .head b { font-size:16px; }
  .mono { font-family:ui-monospace,monospace; font-size:12px; }
  .dim { color:${FAINT}; }
  .use { color:${FAINT}; font-size:12px; }
  .stack { display:flex; flex-direction:column; border:1px solid ${LADDER[3]}; border-radius:10px; overflow:hidden; }
  .step { display:flex; justify-content:space-between; align-items:center; padding:7px 10px; min-height:34px; }
  .step .mono { color:${TEXT}; opacity:.75; }
  .nums { display:flex; gap:14px; margin:12px 0; }
  .warn { border:1px solid #8a5a2a; background:#1a1410; border-radius:8px; padding:8px 10px; font-size:12px; color:#e0b070; margin-bottom:10px; }
  .ok { border:1px solid #2a5a3a; background:#101a13; border-radius:8px; padding:8px 10px; font-size:12px; color:#7fd0a0; margin-bottom:10px; }
  .nums > div { display:flex; flex-direction:column; }
  .k { font-size:11px; color:${FAINT}; }
  .v { font-size:13px; }
  .demo { border:1px solid; border-radius:10px; padding:12px; display:flex; flex-direction:column; gap:10px; }
  .card { border:1px solid; border-radius:8px; padding:10px; display:flex; flex-direction:column; gap:2px; }
  .btn { border:1px solid; border-radius:8px; padding:8px 14px; font:inherit; font-size:13px; cursor:pointer; }
  footer { color:${FAINT}; font-size:12px; margin-top:40px; border-top:1px solid ${LADDER[3]}; padding-top:18px; }
  code { font-family:ui-monospace,monospace; background:${LADDER[1]}; border:1px solid ${LADDER[3]}; border-radius:4px; padding:1px 5px; font-size:12px; }
</style>
</head>
<body>
<div class="wrap">
  <p class="eyebrow">LIMINAL · تست چشمی · تم</p>
  <h1>یک سیستم، پنج هیو</h1>
  <p class="lede">هر مقدار این صفحه توسط <code>createLiminalTheme</code> تولید می‌شود و عددهای زیر هر ستون <b>از نردبان تولیدشده اندازه‌گیری شده‌اند</b>، نه تایپ‌شده.</p>
  <p class="claim">
    ادعایی که این صفحه باید نشان دهد: <b>عوض‌کردن هیو، فاصله‌ی ادراکی سطوح را عوض نمی‌کند.</b>
    گام یک کوانتوم ادراکی است — به این وابسته نیست که نردبان چه رنگی باشد.
    <br>این کل دلیل ساختن نردبان در OKLCH است: <b>هیو حرکت می‌کند، ادراک نه.</b>
  </p>
  <div class="grid">${cols}</div>
  <footer>
    تولید‌شده توسط <code>scripts/gen-theme-test.ts</code> · بدون شبکه ·
    هیوی مرجع ${LADDER_HUE}° · کوانتوم ${PERCEPTUAL_QUANTUM}
  </footer>
</div>
</body>
</html>`;

writeFileSync(OUT, html);
console.log('wrote', OUT, (html.length / 1024).toFixed(1) + 'KB');
